def choose_move(observation):
    # Defensive defaults
    pos = observation.get("position", None)
    grid = observation.get("grid", None)
    mode = observation.get("mode", None)

    # Initialize default move to stay
    dx, dy = 0, 0

    # If detection of a target/resource or opponent exists, try simple heuristics
    if isinstance(grid, (list, tuple)):
        # Look for nearby resource or enemy using simple local scan
        # grid assumed 2D list-like with same dimensions; we scan around current position if possible
        if pos and isinstance(pos, (list, tuple)) and len(pos) >= 2:
            x, y = int(pos[0]), int(pos[1])
            h = len(grid)
            w = len(grid[0]) if h > 0 and isinstance(grid[0], (list, tuple)) else 0

            best_dx, best_dy = 0, 0
            best_score = -10

            for ddx in (-1, 0, 1):
                for ddy in (-1, 0, 1):
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = x + ddx, y + ddy
                    if not (0 <= nx < w and 0 <= ny < h):
                        continue
                    cell = grid[ny][nx] if isinstance(grid[ny], (list, tuple)) and 0 <= ny < h else None
                    score = 0

                    # Resource collection: look for 'R' or numeric positive values
                    if isinstance(cell, str):
                        if cell.lower() == 'r':
                            score += 2
                        if cell.lower() == 'o' or cell.lower() == 'resource':
                            score += 1
                    elif isinstance(cell, (int, float)):
                        if cell > 0:
                            score += 1
                    # Pursuit/Evasion: look for 'E' for enemy
                    if isinstance(cell, str) and cell.lower() == 'e':
                        score += 3

                    if score > best_score:
                        best_score = score
                        best_dx, best_dy = ddx, ddy

            if best_score > 0:
                dx, dy = best_dx, best_dy

    # Fallback simple heuristic based on mode
    if mode == "resource_collection":
        # Move towards a resource if possible by scanning immediate neighbors using simple map hints
        if isinstance(grid, (list, tuple)) and pos:
            x, y = int(pos[0]), int(pos[1])
            # prefer right then down then left then up
            for ddx, ddy in ((1,0),(0,1),(-1,0),(0,-1)):
                nx, ny = x + ddx, y + ddy
                if isinstance(grid, (list, tuple)) and 0 <= ny < len(grid) and 0 <= nx < len(grid[0]):
                    cell = grid[ny][nx]
                    if cell == 'R' or cell == 'resource':
                        dx, dy = ddx, ddy
                        break

    elif mode == "pursuit_evasion":
        # Try to move away from nearest enemy if known
        if isinstance(grid, (list, tuple)) and pos:
            x, y = int(pos[0]), int(pos[1])
            best_dx, best_dy = 0, 0
            max_dist = -1
            for ddx in (-1,0,1):
                for ddy in (-1,0,1):
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = x + ddx, y + ddy
                    if 0 <= ny < len(grid) and 0 <= nx < len(grid[0]):
                        cell = grid[ny][nx]
                        if isinstance(cell, str) and cell.lower() == 'e':
                            dist = abs(ddx) + abs(ddy)
                            if dist > max_dist:
                                max_dist = dist
                                best_dx, best_dy = -ddx, -ddy
            if max_dist >= 0:
                dx, dy = best_dx, best_dy

    elif mode == "territory_control":
        # Prefer staying aligned with own base or central area by moving toward center-ish
        if isinstance(grid, (list, tuple)) and pos:
            x, y = int(pos[0]), int(pos[1])
            h = len(grid)
            w = len(grid[0]) if h > 0 else 0
            if w and h:
                cx, cy = w // 2, h // 2
                dx = 0 if x == cx else (1 if cx > x else -1)
                dy = 0 if y == cy else (1 if cy > y else -1)

    # Final bounds ensure dx, dy in -1..1
    if dx not in (-1, 0, 1) or dy not in (-1, 0, 1):
        dx, dy = 0, 0

    return [dx, dy]

