def choose_move(observation):
    # Minimal deterministic approach: move toward nearest resource if visible, else towards center, else stay.
    grid_w = observation.get("grid_width") or observation.get("grid_width", 0)
    grid_h = observation.get("grid_height") or observation.get("grid_height", 0)
    self_pos = observation.get("self_position") or observation.get("position") or [0, 0]
    opp_pos = observation.get("opponent_position") or observation.get("opponent", [0, 0])
    resources = observation.get("resources") or []
    obstacles = observation.get("obstacles") or []
    rem = observation.get("remaining_resource_count") or 0

    # Normalize to ints
    sx = int(self_pos[0]); sy = int(self_pos[1])
    ox = int(opp_pos[0]); oy = int(opp_pos[1])

    # Helper to clamp move within bounds
    def in_bounds(x, y):
        if grid_w and grid_h:
            return 0 <= x < grid_w and 0 <= y < grid_h
        return True

    # If there is a nearest resource with coordinates, move one step toward it
    best_rx, best_ry = None, None
    if isinstance(resources, (list, tuple)):
        # resources may be list of [x,y] or dicts; support common forms
        for r in resources:
            rx, ry = None, None
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                rx, ry = int(r[0]), int(r[1])
            elif isinstance(r, dict):
                rx = int(r.get("x", 0)); ry = int(r.get("y", 0))
            if rx is None:
                continue
            if best_rx is None or (abs(rx - sx) + abs(ry - sy) < abs(best_rx - sx) + abs(best_ry - sy)):
                best_rx, best_ry = rx, ry

    dx = 0; dy = 0

    if best_rx is not None:
        if best_rx > sx: dx = 1
        elif best_rx < sx: dx = -1
        if best_ry > sy: dy = 1
        elif best_ry < sy: dy = -1
        if dx == 0 and dy == 0:
            dx, dy = 0, 0
        # Ensure not stepping into obstacle if present
        nx, ny = sx + dx, sy + dy
        if obstacles and (nx, ny) in [(o.get("x"), o.get("y")) if isinstance(o, dict) else (o[0], o[1]) for o in obstacles]:
            dx, dy = 0, 0
        if not in_bounds(sx+dx, sy+dy):
            dx, dy = 0, 0
        return [dx, dy]

    # If no resource visible, move toward center of grid if dimensions known
    if grid_w and grid_h:
        cx, cy = grid_w // 2, grid_h // 2
        if sx < cx: dx = 1
        elif sx > cx: dx = -1
        if sy < cy: dy = 1
        elif sy > cy: dy = -1
        nx, ny = sx + dx, sy + dy
        if (nx, ny) in [(o.get("x"), o.get("y")) if isinstance(o, dict) else (o[0], o[1]) for o in obstacles]:
            dx, dy = 0, 0
        if not in_bounds(nx, ny):
            dx, dy = 0, 0
        return [dx, dy]

    # Fallback: do not move
    return [0, 0]
